#!/usr/bin/env bash
# ============================================================================
# demo - Database Initialization Script
# ============================================================================
# Generated by rulebook-to-postgres tool.
#
# Responsibilities: install magic-links auth, run the generated 00-05 SQL,
# regenerate + validate the access-control DDL against the now-live schema,
# then apply it (06+). Skips *.sql.disabled. A freshly created, EMPTY
# database loads to completion in one run.
#
# THIS IS THE DEV LOOP (per plan 04). Re-running against a populated
# DB should be safe — every file is meant to be idempotent. If it
# isn't, fix the file, not this script.
# ============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# The default is DERIVED from the active domain (erb_<domain-with-underscores>,
# matching orchestrate.sh's formula) — the deterministically-correct target, not
# a guess. DATABASE_URL / $1 only OVERRIDE it.
#
# The generated default was `.../demo`, which is exactly the silent-fallback
# shape CLAUDE.md forbids: with ERB_DOMAIN unset it would happily load this
# domain's 50 tables into an unrelated database and still report success.
ERB_DOMAIN="${ERB_DOMAIN:-procedural-knowledge-ontology}"
DEFAULT_CONN="postgresql://postgres@localhost:5432/erb_${ERB_DOMAIN//-/_}"
DATABASE_URL="${DATABASE_URL:-${1:-$DEFAULT_CONN}}"

# ----------------------------------------------------------------------
# Plan 04 §8: bases-URL refusal (defense in depth).
# bases.effortlessapi.com is migration-only. Any rebuild against it
# would drop tables and lose data. Use postgres/apply-migration.sh
# instead. This check has no escape hatch by design.
# ----------------------------------------------------------------------
if echo "$DATABASE_URL" | grep -qi 'bases\.effortlessapi\.com' ; then
    echo "refusing to run init-db.sh against bases." >&2
    echo "bases is migration-only — see CLAUDE.md \"Bases is migration-only\"" >&2
    echo "use postgres/apply-migration.sh postgres/migrations/NNNN-….sql" >&2
    exit 2
fi
if [ -n "${BASES_DATABASE_URL:-}" ] && [ "$DATABASE_URL" = "$BASES_DATABASE_URL" ]; then
    echo "refusing to run init-db.sh: DATABASE_URL == BASES_DATABASE_URL" >&2
    echo "bases is migration-only — use postgres/apply-migration.sh" >&2
    exit 2
fi

echo "[init-db] target: $DATABASE_URL"

# ----------------------------------------------------------------------
# 1. Always (re-)install magic-links auth. Idempotent → safe to repeat.
# ----------------------------------------------------------------------
if [ -f "${SCRIPT_DIR}/install-magic-links.sql" ]; then
    echo "[init-db] [RUN]  install-magic-links.sql"
    psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f "${SCRIPT_DIR}/install-magic-links.sql"
else
    echo "[init-db] note: install-magic-links.sql not present — skipping auth install"
    echo "[init-db]       fetch from https://magiclink.effortlessapi.com/install-magic-links/v1.sql"
fi

# ----------------------------------------------------------------------
# 2. Run the NN[b]?-*.sql files in lex order, in THREE phases. Skip
#    *.sql.disabled.
#
#    Phase A  00-05[b]  schema, calc functions, vw_* views, RLS-enable, data
#    Phase B  regenerate 06-access-control.sql from the rulebook
#    Phase C  06+       access-control DDL, then 99-fk-constraints (opt-in)
#
# The access-control generator VALIDATES against the live database: every
# policy predicate is EXPLAINed against its real public.<table> and every
# granted column is intersected with the real vw_* columns. That schema is
# what Phase A creates, so the generator must run after it -- otherwise a
# freshly created, empty database can never load (consistency rule cr-20:
# no init step may require schema a later step creates). The validation
# stays strict: an invalid predicate still aborts the load before any
# security DDL is applied.
#
# 06-access-control.sql is a PURE FUNCTION of the rulebook's access-control
# tables (AccessPrincipals / AccessPolicies / FieldGrants / RoleSchemas /
# RoleSchemaViews). Regenerating it on every load is what makes "an admin
# edits a policy, saves, and the database reshapes" true -- the DDL is never
# hand-maintained and never stale.
# ----------------------------------------------------------------------
shopt -s nullglob
FILES_RUN=()
FILES_SKIP=()
apply_sql_file() {
    local f="$1"
    [ -f "$f" ] || return 0
    local base; base=$(basename "$f")
    if [[ "$base" == *.disabled ]]; then
        echo "[init-db] [SKIP] $base"
        FILES_SKIP+=("$base")
        return 0
    fi
    # 99-fk-constraints.sql — FK enforcement is opt-in. Demos must never
    # fail on FK violations; the rulebook still documents the relationships
    # and 01-drop-and-create-tables.sql installs the FK indexes inline.
    if [[ "$base" == "99-fk-constraints.sql" && "${EFFORTLESS_ENFORCE_FKS:-false}" != "true" ]]; then
        echo "[init-db] [SKIP] $base (set EFFORTLESS_ENFORCE_FKS=true to apply FK constraints)"
        FILES_SKIP+=("$base")
        return 0
    fi
    echo "[init-db] [RUN]  $base"
    if [[ "$base" == *b-* ]]; then
        # customize files (NNb-*) tolerate per-row errors
        psql "$DATABASE_URL" -f "$f"
    else
        psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f "$f"
    fi
    FILES_RUN+=("$base")
}

# Phase A: the generated substrate (00-05) plus its customize seams.
for f in "${SCRIPT_DIR}"/0[0-5]*-*.sql "${SCRIPT_DIR}"/0[0-5]*-*.sql.disabled; do
    apply_sql_file "$f"
done

# Phase B: regenerate the access-control DDL against the now-live schema.
GEN="${SCRIPT_DIR}/../tools/generate_access_ddl.py"
[ -f "$GEN" ] || { echo "[init-db] FATAL: access-control generator is missing: $GEN" >&2; exit 1; }
echo "[init-db] regenerating access-control DDL from the rulebook (validated against $DATABASE_URL)"
if ! DATABASE_URL="$DATABASE_URL" python3 "$GEN"; then
    echo "[init-db] FATAL: access-control DDL generation failed." >&2
    echo "[init-db] Fix the offending policy in the rulebook and re-run." >&2
    exit 1
fi

# Phase C: access control and everything numbered after it (99-fk is opt-in).
for f in "${SCRIPT_DIR}"/0[6-9]*-*.sql "${SCRIPT_DIR}"/0[6-9]*-*.sql.disabled \
         "${SCRIPT_DIR}"/[1-9][0-9]*-*.sql "${SCRIPT_DIR}"/[1-9][0-9]*-*.sql.disabled; do
    apply_sql_file "$f"
done

# ----------------------------------------------------------------------
# 3. function-overrides/*.sql (per-function tweaks; errors non-fatal).
#    Two-pass: non-policy files first, then policy__* files (policies
#    often reference custom functions).
# ----------------------------------------------------------------------
run_override() {
    local sql_file="$1"
    local base; base=$(basename "$sql_file")
    if [[ "$base" == *.disabled ]]; then
        echo "[init-db] [SKIP] function-overrides/$base"
        return 0
    fi
    echo "[init-db] [RUN]  function-overrides/$base"
    psql "$DATABASE_URL" -f "$sql_file" || echo "[init-db] [WARN] $base failed (non-fatal)"
}
if compgen -G "${SCRIPT_DIR}/function-overrides/*.sql" > /dev/null 2>&1; then
    for sql_file in "${SCRIPT_DIR}/function-overrides/"*.sql; do
        base=$(basename "$sql_file")
        [[ "$base" == policy__* ]] && continue
        run_override "$sql_file"
    done
    for sql_file in "${SCRIPT_DIR}/function-overrides/"policy__*.sql; do
        [[ -f "$sql_file" ]] || continue
        run_override "$sql_file"
    done
fi

# ----------------------------------------------------------------------
# 4. Plan 04 §9: write postgres/.applied-manifest.json so tooling can
#    compare to .build-manifest.json and detect drift.
# ----------------------------------------------------------------------
APPLIED_AT="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
MANIFEST="${SCRIPT_DIR}/.applied-manifest.json"
{
    printf '{\n'
    printf '  "applied_at": "%s",\n' "$APPLIED_AT"
    printf '  "target": "%s",\n' "$DATABASE_URL"
    printf '  "files_run": ['
    sep=''
    for f in "${FILES_RUN[@]:-}"; do
        [ -z "$f" ] && continue
        printf '%s"%s"' "$sep" "$f"
        sep=','
    done
    printf '],\n'
    printf '  "files_skipped": ['
    sep=''
    for f in "${FILES_SKIP[@]:-}"; do
        [ -z "$f" ] && continue
        printf '%s"%s"' "$sep" "$f"
        sep=','
    done
    printf ']\n'
    printf '}\n'
} > "$MANIFEST"

echo "[init-db] complete (manifest: .applied-manifest.json)"
